            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;Les tactiques des arm&#233;es&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;La victoire, la d&#233;route et la d&#233;faite&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Commandants-(Guerre).html&quot; title=&quot;Les commandants&quot;&gt;Les commandants&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ressources-Des-Arm&#233;es-(Guerre).html&quot; title=&quot;Les ressources des arm&#233;es&quot;&gt;Les ressources des arm&#233;es&lt;/a&gt;&lt;/li&gt;
            &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Les pouvoirs sp&#233;ciaux&lt;/a&gt;&lt;/li&gt;
